  var VARIANTS = [
    { key: "cooked", de: "gekocht", it: "cotto", en: "cooked", factor: 0.72 },
    { key: "boiled", de: "in Wasser gekocht", it: "lessato", en: "boiled", factor: 0.7 },
    { key: "grilled", de: "gegrillt", it: "alla griglia", en: "grilled", factor: 0.82, addFat: 1 },
    { key: "steamed", de: "ged\xE4mpft", it: "al vapore", en: "steamed", factor: 0.9 },
    { key: "baked", de: "im Ofen gebacken", it: "al forno", en: "oven-baked", factor: 0.85, addFat: 1 },
    { key: "roasted", de: "ger\xF6stet", it: "arrosto", en: "roasted", factor: 0.88, addFat: 1.5 },
    { key: "fried", de: "in der Pfanne gebraten", it: "in padella", en: "pan-fried", factor: 0.86, addFat: 6 },
    { key: "airfried", de: "in der Hei\xDFluftfritteuse", it: "in friggitrice ad aria", en: "air-fried", factor: 0.84 }
  ];
  var slug = (s) => s.toLowerCase().replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
  var parseRows = () => ROWS.trim().split("\n").map((line) => line.split("|").map((x) => x.trim())).filter((c) => c.length >= 12);
  var EXTRA_FOODS = (() => {
    const out = [];
    for (const c of parseRows()) {
      const [de, it, en, kcal, carbs, protein, fat, fiber, salt, category, unit, cookable] = c;
      const base = {
        id: `genx-${slug(en)}`,
        name_de: de,
        name_it: it,
        name_en: en,
        store: "Generic",
        category,
        unit: unit === "ml" ? "ml" : "g",
        calories: Number(kcal),
        carbs: Number(carbs),
        protein: Number(protein),
        fat: Number(fat),
        fiber: Number(fiber),
        salt: Number(salt)
      };
      out.push(base);
      if (cookable === "1") {
        for (const v of VARIANTS) {
          const f = v.factor;
          out.push({
            ...base,
            id: `${base.id}-${v.key}`,
            name_de: `${de} ${v.de}`,
            name_it: `${it} ${v.it}`,
            name_en: `${en} (${v.en})`,
            calories: Math.round(base.calories * f + (v.addFat || 0) * 9),
            carbs: Math.round((base.carbs || 0) * f * 10) / 10,
            protein: Math.round((base.protein || 0) * f * 10) / 10,
            fat: Math.round(((base.fat || 0) * f + (v.addFat || 0)) * 10) / 10,
            fiber: base.fiber !== null ? Math.round(base.fiber * f * 10) / 10 : null,
            salt: base.salt
          });
        }
      }
    }
    return out;
  })();

